      {
        h: 'まとめ',
        html: '<ul><li><b class="key">制限酵素</b>で切り、<b class="key">DNAリガーゼ</b>でつなぎ、<b class="key">プラスミド</b>などの<b class="key">ベクター</b>で細胞に運ぶ。</li><li><b class="key">PCR法</b>は 95℃→60℃→72℃ のくり返し。n サイクルで 2<sup>n</sup> 倍。</li><li><b class="key">電気泳動</b>では DNA は陽極へ動き、短いものほど遠くへ移動する。</li><li><b class="key">ゲノム編集</b>はねらった配列を切って書きかえる。<b class="key">iPS細胞</b>は体細胞からつくる多能性の細胞。</li></ul>',
        fig: '<svg viewBox="0 0 480 360" xmlns="http://www.w3.org/2000/svg"><text x="240" y="20" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">まとめ：遺伝子を扱う道具</text><rect x="10" y="40" width="140" height="64" rx="6" fill="var(--c1)" fill-opacity="0.15" stroke="var(--ink)" stroke-width="1.5"/><text x="80" y="67.9" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">切る</text><text x="80" y="86.9" fill="var(--ink)" font-size="12" text-anchor="middle">制限酵素（GAATTC）</text><line x1="150" y1="72" x2="163.6" y2="72.0" stroke="var(--ink)" stroke-width="1.5"/><polygon points="170.0,72.0 162.0,67.6 162.0,76.4" fill="var(--ink)"/><rect x="170" y="40" width="140" height="64" rx="6" fill="var(--c1)" fill-opacity="0.15" stroke="var(--ink)" stroke-width="1.5"/><text x="240" y="67.9" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">つなぐ</text><text x="240" y="86.9" fill="var(--ink)" font-size="12" text-anchor="middle">DNAリガーゼ</text><line x1="310" y1="72" x2="323.6" y2="72.0" stroke="var(--ink)" stroke-width="1.5"/><polygon points="330.0,72.0 322.0,67.6 322.0,76.4" fill="var(--ink)"/><rect x="330" y="40" width="140" height="64" rx="6" fill="var(--c1)" fill-opacity="0.15" stroke="var(--ink)" stroke-width="1.5"/><text x="400" y="67.9" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">運ぶ</text><text x="400" y="86.9" fill="var(--ink)" font-size="12" text-anchor="middle">プラスミドなど</text><text x="240" y="120" fill="var(--muted)" font-size="12" text-anchor="middle">遺伝子組換え → 大腸菌にインスリンをつくらせる</text><rect x="10" y="140" width="140" height="70" rx="6" fill="var(--c3)" fill-opacity="0.15" stroke="var(--ink)" stroke-width="1.5"/><text x="80" y="163.4" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">ふやす</text><text x="80" y="180.4" fill="var(--ink)" font-size="12" text-anchor="middle">PCR法</text><text x="80" y="197.4" fill="var(--ink)" font-size="12" text-anchor="middle">95℃→60℃→72℃</text><line x1="150" y1="175" x2="163.6" y2="175.0" stroke="var(--ink)" stroke-width="1.5"/><polygon points="170.0,175.0 162.0,170.6 162.0,179.4" fill="var(--ink)"/><rect x="170" y="140" width="140" height="70" rx="6" fill="var(--c3)" fill-opacity="0.15" stroke="var(--ink)" stroke-width="1.5"/><text x="240" y="163.4" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">調べる</text><text x="240" y="180.4" fill="var(--ink)" font-size="12" text-anchor="middle">電気泳動</text><text x="240" y="197.4" fill="var(--ink)" font-size="12" text-anchor="middle">短いほど遠く・陽極へ</text><line x1="310" y1="175" x2="323.6" y2="175.0" stroke="var(--ink)" stroke-width="1.5"/><polygon points="330.0,175.0 322.0,170.6 322.0,179.4" fill="var(--ink)"/><rect x="330" y="140" width="140" height="70" rx="6" fill="var(--c3)" fill-opacity="0.15" stroke="var(--ink)" stroke-width="1.5"/><text x="400" y="163.4" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">使う</text><text x="400" y="180.4" fill="var(--ink)" font-size="12" text-anchor="middle">DNA型鑑定</text><text x="400" y="197.4" fill="var(--ink)" font-size="12" text-anchor="middle">親子鑑定・捜査</text><text x="80" y="226" fill="var(--muted)" font-size="12" text-anchor="middle">n サイクルで 2ⁿ 倍</text><rect x="10" y="246" width="225" height="70" rx="6" fill="var(--accent)" fill-opacity="0.2" stroke="var(--ink)" stroke-width="1.5"/><text x="122.5" y="269.4" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">書きかえる</text><text x="122.5" y="286.4" fill="var(--ink)" font-size="12" text-anchor="middle">ゲノム編集（CRISPR/Cas9）</text><text x="122.5" y="303.4" fill="var(--ink)" font-size="12" text-anchor="middle">ねらった配列を切る</text><rect x="245" y="246" width="225" height="70" rx="6" fill="var(--accent)" fill-opacity="0.2" stroke="var(--ink)" stroke-width="1.5"/><text x="357.5" y="269.4" fill="var(--ink)" font-size="15" text-anchor="middle" font-weight="bold">つくる</text><text x="357.5" y="286.4" fill="var(--ink)" font-size="12" text-anchor="middle">iPS細胞</text><text x="357.5" y="303.4" fill="var(--ink)" font-size="12" text-anchor="middle">体細胞 ＋ 遺伝子 → 多能性</text><text x="240" y="342" fill="var(--muted)" font-size="12" text-anchor="middle">安全性・生態系・個人情報に配慮してルールの下で使う</text></svg>'
      }
